import json
import sys

data = []
for line in sys.stdin:
    if line.strip():
        data.append(json.loads(line))

# Find Screen lock and Encryption
security_items = {}
for item in data:
    if 'label' in item and item['label'] in ['Screen lock', 'Encryption', 'Notifications']:
        security_items[item['label']] = {
            'index': item['index'],
            'parentIndex': item.get('parentIndex'),
            'type': item['type']
        }

# Print hierarchy
for label, info in security_items.items():
    print(f"\n{label}:")
    print(f"  Index: {info['index']}")
    print(f"  Parent Index: {info['parentIndex']}")

    # Find parent element
    for item in data:
        if item['index'] == info['parentIndex']:
            print(f"  Parent Type: {item.get('type')}")
            print(f"  Parent Label: {item.get('label')}")
            if 'parentIndex' in item:
                # Find grandparent
                for gp in data:
                    if gp['index'] == item['parentIndex']:
                        print(f"  Grandparent Type: {gp.get('type')}")
                        print(f"  Grandparent Label: {gp.get('label')}")
EOF

